function emptyWeek(){const w={};for(let d=0;d<7;d++)w[d]={enabled:false,segments:[],start:'09:00',end:'18:00',breakMinutes:0};return w}
function normalizeScheduleDay(raw){
  const source=raw||{};
  let segments=Array.isArray(source.segments)?source.segments:[];
  if(!segments.length&&source.enabled)segments=[{segmentNo:1,start:source.start||'09:00',end:source.end||'18:00',breakMinutes:+source.breakMinutes||0}];
  segments=segments.filter(Boolean).map((x,i)=>({segmentNo:+x.segmentNo||i+1,start:String(x.start||'09:00').slice(0,5),end:String(x.end||'18:00').slice(0,5),breakMinutes:+x.breakMinutes||0})).sort((a,b)=>a.segmentNo-b.segmentNo);
  return {enabled:segments.length>0,segments,start:segments[0]?.start||'09:00',end:segments.at(-1)?.end||'18:00',breakMinutes:segments.reduce((n,x)=>n+(+x.breakMinutes||0),0)};
}
function scheduleLabel(s){const d=normalizeScheduleDay(s);return d.enabled?d.segments.map(x=>`${x.start}–${x.end}`).join(' · '):'Folga'}
function zonedParts(date=new Date(),withTime=false){const options={timeZone:APP_TIME_ZONE,year:'numeric',month:'2-digit',day:'2-digit'};if(withTime)Object.assign(options,{hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});const parts=new Intl.DateTimeFormat('en-GB',options).formatToParts(date),o={};parts.forEach(p=>o[p.type]=p.value);return {year:+o.year,month:+o.month,day:+o.day,hour:withTime?+o.hour:0,minute:withTime?+o.minute:0,second:withTime?+o.second:0}}
function localDate(date=new Date()){const p=zonedParts(date);return `${p.year}-${String(p.month).padStart(2,'0')}-${String(p.day).padStart(2,'0')}`}
function dateOnlyUTC(date){if(!/^\d{4}-\d{2}-\d{2}$/.test(String(date||'')))return NaN;const [y,m,d]=date.split('-').map(Number);return Date.UTC(y,m-1,d)}
function shiftDateString(date,days){const ms=dateOnlyUTC(date);if(!Number.isFinite(ms))return date;const x=new Date(ms);x.setUTCDate(x.getUTCDate()+days);return x.toISOString().slice(0,10)}
function dateOffset(days,base=new Date()){return shiftDateString(localDate(base),days)}
const offsetCache=new Map();
function zonedOffsetsForDate(date){if(offsetCache.has(date))return offsetCache.get(date);const [y,m,d]=date.split('-').map(Number),center=Date.UTC(y,m-1,d,12),set=new Set();for(let h=-36;h<=36;h+=12){const i=new Date(center+h*3600000),p=zonedParts(i,true),shown=Date.UTC(p.year,p.month-1,p.day,p.hour,p.minute,p.second);set.add(Math.round((shown-i.getTime())/60000))}const r=[...set];offsetCache.set(date,r);return r}
function zonedDateTimeInfo(date,time){if(!/^\d{4}-\d{2}-\d{2}$/.test(String(date||''))||!/^\d{2}:\d{2}$/.test(String(time||'')))return {valid:false,ambiguous:false,candidates:[]};const [y,m,d]=date.split('-').map(Number),[hh,mm]=time.split(':').map(Number),target=Date.UTC(y,m-1,d,hh,mm),c=zonedOffsetsForDate(date).map(o=>new Date(target-o*60000)).filter(i=>{const p=zonedParts(i,true);return p.year===y&&p.month===m&&p.day===d&&p.hour===hh&&p.minute===mm}).sort((a,b)=>a-b),u=c.filter((x,i,a)=>i===0||+x!==+a[i-1]);return {valid:u.length>0,ambiguous:u.length>1,candidates:u}}
function zonedDateTime(date,time,preference='earlier'){const i=zonedDateTimeInfo(date,time);if(!i.valid)return new Date(NaN);return new Date((preference==='later'?i.candidates.at(-1):i.candidates[0]).getTime())}
function timeMinutes(v){if(!/^\d{2}:\d{2}$/.test(String(v||'')))return NaN;const [h,m]=String(v).split(':').map(Number);return h>=0&&h<24&&m>=0&&m<60?h*60+m:NaN}
function dayIndex(date){const ms=dateOnlyUTC(date);return Number.isFinite(ms)?new Date(ms).getUTCDay():0}
function fmtDate(date){const ms=dateOnlyUTC(date);return Number.isFinite(ms)?new Intl.DateTimeFormat('pt-PT',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(ms+43200000)):'—'}
function fmtTime(iso){return iso?new Intl.DateTimeFormat('pt-PT',{hour:'2-digit',minute:'2-digit',timeZone:APP_TIME_ZONE}).format(new Date(iso)):'—'}
function fmtDateTime(iso){return iso?new Intl.DateTimeFormat('pt-PT',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:APP_TIME_ZONE}).format(new Date(iso)):'—'}
function minsLabel(mins){mins=Math.max(0,Math.round(mins||0));const h=Math.floor(mins/60),m=mins%60;return h?`${h}h ${String(m).padStart(2,'0')}m`:`${m}m`}
function initials(n){return String(n||'?').split(/\s+/).filter(Boolean).map(x=>x[0]).slice(0,2).join('').toUpperCase()}
function validateDateRange(start,end,maxDays=366){const a=dateOnlyUTC(start),b=dateOnlyUTC(end);if(!Number.isFinite(a)||!Number.isFinite(b))return {ok:false,message:'Seleciona um intervalo válido.'};if(b<a)return {ok:false,message:'A data final não pode ser anterior à inicial.'};const days=Math.round((b-a)/86400000)+1;return days>maxDays?{ok:false,message:`Máximo de ${maxDays} dias de calendário.`}:{ok:true,days}}

function monthKey(date=localDate()){return String(date).slice(0,7)}
function monthBounds(month){if(!/^\d{4}-\d{2}$/.test(String(month||'')))return null;const [y,m]=month.split('-').map(Number);if(m<1||m>12)return null;const last=new Date(Date.UTC(y,m,0)).getUTCDate();return {start:`${month}-01`,end:`${month}-${String(last).padStart(2,'0')}`}}
function shiftMonth(month,delta){const [y,m]=String(month).split('-').map(Number),d=new Date(Date.UTC(y,m-1+delta,1));return d.toISOString().slice(0,7)}
function fmtMonth(month){const [y,m]=String(month).split('-').map(Number),v=new Intl.DateTimeFormat('pt-PT',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(Date.UTC(y,m-1,15)));return v.charAt(0).toUpperCase()+v.slice(1)}
function monthStatus(month){const current=monthKey(),bounds=monthBounds(month),isCurrent=month===current;return {...bounds,isCurrent,actualEnd:isCurrent?localDate():bounds.end,label:isCurrent?'Mês atual · em curso':'Histórico mensal'}}

function monthClosure(month){return (db.monthClosures||[]).find(x=>String(x.month).slice(0,7)===month)||null}
function monthClosed(month){return !!monthClosure(month)?.closed}
function payrollClosure(month){return (db.payrollClosures||[]).find(x=>x.active&&String(x.month).slice(0,7)===month)||null}
function payrollSnapshotsFor(closureId){return (db.payrollSnapshots||[]).filter(x=>x.closureId===closureId)}
function signedMinutes(mins){const n=Math.round(mins||0),a=Math.abs(n),h=Math.floor(a/60),m=a%60,v=h?`${h}h ${String(m).padStart(2,'0')}m`:`${m}m`;return n>0?`+${v}`:n<0?`−${v}`:'0m'}
function workedRange(user,start,end){let minutes=0;if(!start||!end||end<start)return 0;for(let d=start;d<=end;d=shiftDateString(d,1)){const a=analysis(user,d);if(a.ci)minutes+=a.worked}return minutes}
function carryFromPreviousMonth(user,month){const prev=shiftMonth(month,-1),c=payrollClosure(prev);if(!c)return 0;const snap=payrollSnapshotsFor(c.id).find(x=>x.userId===user.id);if(!snap)return 0;const end=monthBounds(prev)?.end,start=shiftDateString(c.cutoffDate,1);if(!end||start>end)return 0;return workedRange(user,start,end)-snap.projectedRemainingMinutes}
function liveCarryAfterEarlyClose(user,month){const c=payrollClosure(month);if(!c)return 0;const snap=payrollSnapshotsFor(c.id).find(x=>x.userId===user.id);if(!snap)return 0;const bounds=monthBounds(month),lastComplete=shiftDateString(localDate(),-1),end=lastComplete<bounds.end?lastComplete:bounds.end,start=shiftDateString(c.cutoffDate,1);if(start>end)return 0;const actual=workedRange(user,start,end),planned=plannedRange(user,start,end).minutes;return actual-planned}
function monthEarlyClosePreview(users,range){const cutoff=shiftDateString(localDate(),-1),remainingStart=localDate();return users.map(u=>{const actual=workedRange(u,range.start,cutoff),projected=remainingStart<=range.end?plannedRange(u,remainingStart,range.end).minutes:0,carry=carryFromPreviousMonth(u,range.start.slice(0,7));return {u,actual,projected,carry,total:actual+projected+carry}})}
function csvEscape(v){const x=String(v??'');return /[",\n]/.test(x)?'"'+x.replace(/"/g,'""')+'"':x}
function downloadText(name,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),500)}
function auditActionLabel(a){return ({employee_created:'Funcionário criado',employee_network_mode_changed:'Regra de rede alterada',network_exception_created:'Exceção de rede criada',network_exception_cancelled:'Exceção de rede cancelada',punch_created:'Picagem registada',punch_updated:'Picagem alterada',punch_deleted:'Picagem removida',correction_requested:'Correção pedida',correction_approved:'Correção aprovada',correction_rejected:'Correção rejeitada',month_closed:'Mês fechado',month_reopened:'Mês reaberto',payroll_month_finalized_early:'Mês finalizado antecipadamente',payroll_month_reopened:'Processamento mensal reaberto',onboarding_invite_created:'Convite de acesso criado',onboarding_invite_used:'Convite de acesso utilizado',employee_worksites_changed:'Locais do funcionário alterados',worksite_created:'Estabelecimento criado',worksite_updated:'Estabelecimento atualizado',owner_created:'Acesso do proprietário criado',operational_area_created:'Área criada',operational_area_updated:'Área atualizada',area_tasks_changed:'Obrigações da área alteradas',employee_area_changed:'Área do funcionário alterada',employee_removed:'Funcionário removido da equipa'})[a]||a}
function auditDetail(x){if(x.action==='payroll_month_finalized_early')return `Corte ${x.metadata?.cutoff_date||'—'} · ${x.metadata?.employee_count||0} funcionários`;if(x.action==='payroll_month_reopened')return x.metadata?.reason||'Processamento reaberto';if(x.action==='month_reopened')return x.metadata?.reason||'Mês reaberto';if(x.action==='network_exception_created')return x.metadata?.reason||'Trabalho externo';if(x.action==='employee_worksites_changed')return 'Locais autorizados atualizados';return x.metadata?.reason||x.detail||x.entityType||'—'}

function scheduleWeekFor(user,date){const h=(user?.scheduleHistory||[]).filter(v=>v.effectiveFrom<=date).sort((a,b)=>a.effectiveFrom.localeCompare(b.effectiveFrom)||(a.revision||1)-(b.revision||1)),v=h.at(-1);if(!v)return emptyWeek();const w=clone(v.week);for(let d=0;d<7;d++)w[d]=normalizeScheduleDay(w[d]);return w}
function scheduleFor(user,date){const removed=removedEmployeeDate(user);if(removed&&date>=removed)return normalizeScheduleDay(null);return normalizeScheduleDay(scheduleWeekFor(user,date)?.[dayIndex(date)])}
function scheduleSegmentsFor(user,date){return scheduleFor(user,date).segments}
function scheduleSegmentTimes(date,s){if(!s)return {start:null,end:null,overnight:false};const a=timeMinutes(s.start),b=timeMinutes(s.end);if(!Number.isFinite(a)||!Number.isFinite(b)||a===b)return {start:null,end:null,overnight:false};const overnight=b<a,start=zonedDateTime(date,s.start,'earlier'),end=zonedDateTime(overnight?shiftDateString(date,1):date,s.end,'later'),sv=Number.isFinite(start.getTime()),ev=Number.isFinite(end.getTime());if(!sv||!ev)return {start:sv?start:null,end:ev?end:null,overnight,temporalIssue:'nonexistent_schedule_time'};return {start,end,overnight}}
