function openJourneyDate(user,now=new Date()){const today=localDate(now),dates=[today,shiftDateString(today,-1),shiftDateString(today,-2)];let best=null;for(const d of dates){const groups=punchGroups(punchesFor(user.id,d));for(const [shiftNo,rows] of groups){const ci=rows.find(x=>x.type==='clock_in'),co=rows.find(x=>x.type==='clock_out');if(ci&&!co&&(!best||new Date(ci.at)>new Date(best.ci.at)))best={date:d,shiftNo,scheduleSegmentNo:ci.scheduleSegmentNo||null,ci}}}return best}
function resolveJourneyDate(user,now=new Date()){const open=openJourneyDate(user,now);if(open)return open.date;const today=localDate(now),prev=shiftDateString(today,-1),m=new Date(now);for(const seg of scheduleSegmentsFor(user,prev)){const t=scheduleSegmentTimes(prev,seg);if(t.overnight&&t.start&&t.end&&m>=t.start&&m<=t.end)return prev}return today}
