function shiftWorkedMinutes(rows,now=new Date(),user=null,date=null,shiftNo=1){let total=0,segment=null,effective=now,ci=rows.find(p=>p.type==='clock_in'),co=rows.find(p=>p.type==='clock_out'),scheduleSegmentNo=ci?.scheduleSegmentNo||rows.find(p=>p.scheduleSegmentNo)?.scheduleSegmentNo||null;if(ci&&user&&date&&!co){const cap=journeySafetyEnd(user,date,ci.at,shiftNo,scheduleSegmentNo);if(effective>cap)effective=cap}for(const p of rows){const t=new Date(p.at);if(p.type==='clock_in'||p.type==='break_end')segment=t;if(p.type==='break_start'||p.type==='clock_out'){if(segment&&t>=segment){total+=(t-segment)/60000;segment=null}}}if(segment&&!co&&effective>segment)total+=(effective-segment)/60000;return Math.max(0,Math.floor(total))}
