function setButtonBusy(button,busy,label='A processar…'){if(!button)return;if(busy){if(!button.dataset.oldLabel)button.dataset.oldLabel=button.textContent;button.textContent=label;button.disabled=true;button.classList.add('is-busy')}else{button.textContent=button.dataset.oldLabel||'Entrar';button.disabled=false;button.classList.remove('is-busy');delete button.dataset.oldLabel}}
