function networkStatusMarkup(){
  if(!navigator.onLine)return '<div class="network-state danger"><strong>Sem ligação à Internet</strong><span>A picagem não será enviada até recuperares a ligação.</span></div>';
  if(!db.company.networkEnforcementEnabled)return '<div class="network-state neutral"><strong>Rede livre durante testes</strong><span>A restrição do estabelecimento ainda está desligada.</span></div>';
  if(!networkStatus)return '<div class="network-state neutral"><strong>A verificar rede…</strong><span>Confirmação automática do local.</span></div>';
  if(networkStatus.matched)return `<div class="network-state ok"><strong>${esc(networkStatus.worksite?.name||'Rede autorizada')} ✓</strong><span>Podes registar normalmente.</span></div>`;
  if(networkStatus.permanentException)return '<div class="network-state ok"><strong>Trabalho externo autorizado</strong><span>Tens permissão permanente para picar fora da rede.</span></div>';
  if(networkStatus.temporaryException)return `<div class="network-state ok"><strong>Exceção temporária ativa</strong><span>Até ${fmtDateTime(networkStatus.temporaryException.ends_at)} · ${esc(networkStatus.temporaryException.reason||'Trabalho externo')}</span></div>`;
  return '<div class="network-state danger"><strong>Fora da rede autorizada</strong><span>Precisas da rede do restaurante ou de uma exceção da administração.</span></div>';
}
async function refreshNetworkStatus(){
  if(currentUser?.role!=='employee')return;
  if(!navigator.onLine){networkStatus=null;updateNetworkStatusUI();return}
  try{networkStatus=await edge('worktime-network-status',{});}catch{networkStatus=null}
  updateNetworkStatusUI();
}
function updateNetworkStatusUI(){const el=$('#networkStatusCard');if(el)el.innerHTML=networkStatusMarkup()}
