async function requestReminders(){
  if(!('Notification' in window))return toast('Este dispositivo não suporta notificações.','error');
  const p=await Notification.requestPermission();
  toast(p==='granted'?'Lembretes ativados neste dispositivo.':'As notificações não foram autorizadas.',p==='granted'?'success':'error');
  renderCurrent();
}
async function notifyLocal(title,body,key){
  if(Notification.permission!=='granted'||notifiedReminderKeys.has(key))return;
  notifiedReminderKeys.add(key);
  try{const reg=await navigator.serviceWorker?.ready;if(reg)await reg.showNotification(title,{body,icon:'assets/icons/icon-192.png',badge:'assets/icons/icon-192.png',tag:key});else new Notification(title,{body})}catch{}
}
function checkEmployeeReminders(){
  if(currentUser?.role!=='employee'||Notification.permission!=='granted'||!navigator.onLine)return;
  const date=resolveJourneyDate(currentUser),a=analysis(currentUser,date,new Date()),now=Date.now();
  if(a.openShift?.ci){const seg=a.segments[(a.openShift.scheduleSegmentNo||a.openShift.shiftNo||1)-1],t=seg?scheduleSegmentTimes(date,seg):null;if(t?.end&&now>t.end.getTime()+10*60000)notifyLocal('Turno ainda aberto','O horário previsto já terminou. Confirma se falta registar a saída.',`open-${currentUser.id}-${date}-${a.openShift.shiftNo}`)}
  if(date===localDate()&&!a.ci&&a.segments.length){const t=scheduleSegmentTimes(date,a.segments[0]);if(t?.start&&now>t.start.getTime()+10*60000&&now<t.start.getTime()+180*60000)notifyLocal('Entrada por registar','O teu turno já começou e ainda não existe uma entrada registada.',`entry-${currentUser.id}-${date}`)}
}
function setupReminderLoop(){clearInterval(reminderTimer);reminderTimer=setInterval(checkEmployeeReminders,60000);checkEmployeeReminders()}
function confirmationMarkup(){if(!lastPunchConfirmation||Date.now()-lastPunchConfirmation.at>120000)return '';return `<div class="punch-confirmation"><strong>${esc(lastPunchConfirmation.label)} ✓</strong><span>${esc(lastPunchConfirmation.detail)}</span></div>`}
function employeeObligationsPreview(){
  const area=areaById(currentUser?.areaId);if(!area)return '';
  if(currentUser.specialRole==='room_manager'){const date=localDate(),tasks=tasksForArea(area.id),done=tasks.filter(t=>taskState(t.id,date)?.completed).length;return `<button id="openRoomOperations" class="employee-ops-preview manager-preview" type="button"><span class="employee-ops-preview-copy"><small>${esc(area.name)} · supervisão</small><strong>${done} de ${tasks.length} concluídas hoje</strong><span>Ver quem fez e histórico dos últimos 7 dias</span></span><span class="employee-ops-preview-arrow">›</span></button>`;}
  if(currentUser.participatesInObligations===false)return '';
  const date=localDate(),tasks=tasksForArea(area.id);if(!tasks.length)return '';
  const done=tasks.filter(t=>taskState(t.id,date)?.completed).length,remaining=Math.max(0,tasks.length-done),pct=Math.round(done/tasks.length*100);
  return `<button id="openObligations" class="employee-ops-preview" type="button"><span class="employee-ops-preview-copy"><small>${esc(area.name)} · hoje</small><strong>${remaining?`${remaining} ${remaining===1?'obrigação por fazer':'obrigações por fazer'}`:'Tudo concluído'}</strong><span>${done} de ${tasks.length} concluídas</span></span><span class="employee-ops-preview-progress" style="--ops-progress:${pct}%"><b>${pct}%</b></span><span class="employee-ops-preview-arrow">›</span></button>`;
}
