async function submitPunch(type){const b=type==='no_break'?$('#noBreakBtn'):$('#punchBtn');if(!navigator.onLine)return toast('Sem ligação. A picagem não foi registada.','error');try{setButtonBusy(b,true,'A registar…');const result=await edge('worktime-punch',{type});const when=fmtTime(result?.punch?.occurred_at||new Date().toISOString()),where=result?.networkVerified?(result?.worksite?.name||'rede autorizada'):result?.networkAccessType==='temporary_exception'?'trabalho externo autorizado':result?.networkAccessType==='permanent_exception'?'exceção permanente':'registado';lastPunchConfirmation={at:Date.now(),label:`${PUNCH_LABELS[type]} registada às ${when}`,detail:where};await refresh();toast(`${PUNCH_LABELS[type]} registada com sucesso.`,'success')}catch(e){setButtonBusy(b,false);toast(e.message||'Não foi possível registar.','error');refreshNetworkStatus();renderCurrent()}}
