function employeesForMonth(start,end){return allEmployeesIncludingRemoved().filter(u=>{const created=String(u.createdAt||'').slice(0,10),existsByDate=!created||created<=end,hasSchedule=(u.scheduleHistory||[]).some(v=>v.effectiveFrom<=end),hasPunch=db.punches.some(p=>p.userId===u.id&&p.journeyDate>=start&&p.journeyDate<=end),hasStatus=db.dayStatuses.some(x=>x.userId===u.id&&x.date>=start&&x.date<=end);return existsByDate&&(!removedEmployeeDate(u)||start<removedEmployeeDate(u))&&(hasSchedule||hasPunch||hasStatus)})}
function plannedRange(user,start,end){let minutes=0,days=0;if(!start||!end||end<start)return {minutes,days};for(let d=start;d<=end;d=shiftDateString(d,1)){const s=scheduleFor(user,d);if(s.enabled){days++;minutes+=plannedMinutes(s,d)}}return {minutes,days}}
function monthlyStatsFor(user,range){const full=plannedRange(user,range.start,range.end),elapsed=plannedRange(user,range.start,range.actualEnd),x={u:user,plannedMonth:full.minutes,plannedDays:full.days,plannedElapsed:elapsed.minutes,elapsedDays:elapsed.days,worked:0,completed:0,late:0,extra:0,deficit:0,absences:0,incomplete:0};for(let d=range.start;d<=range.actualEnd;d=shiftDateString(d,1)){const a=analysis(user,d);if(a.ci)x.worked+=a.worked;if(a.classification==='completed')x.completed++;if(a.late)x.late+=a.late;if(a.extra)x.extra+=a.extra;if(a.deficit)x.deficit+=a.deficit;if(['absence','unjustified_absence','justified_absence'].includes(a.classification))x.absences++;if(a.classification==='incomplete')x.incomplete++}return x}
